jsxGraph.script:
board.suspendUpdate();
var pA = board.create('point', [2, 3], {size: 3, color: 'black', name: 'A(2, 3)', withLabel: true, label: {autoPosition: false, offset: [-20, 10]}});
var pB = board.create('point', [6, 7], {size: 3, color: 'black', name: 'B(6, 7)', withLabel: true, label: {autoPosition: false, offset: [10, 10]}});
var pC = board.create('point', [9, 1], {size: 3, color: 'black', name: 'C(9, 1)', withLabel: true, label: {autoPosition: false, offset: [10, -5]}});
var pD = board.create('point', [7, -3], {size: 3, color: 'black', name: 'D(7, -3)', withLabel: true, label: {autoPosition: false, offset: [-15, -15]}});
board.create('polygon', [pA, pB, pC, pD], {fillColor: 'none', borders: {strokeColor: 'black', strokeWidth: 1}});
var pM = board.create('point', [4, 5], {size: 3, color: 'blue', name: 'M(4, 5)', withLabel: true, label: {autoPosition: false, offset: [-15, 10]}});
var pN = board.create('point', [8, -1], {size: 3, color: 'blue', name: 'N(8, -1)', withLabel: true, label: {autoPosition: false, offset: [10, 5]}});
board.create('line', [pM, pN], {strokeColor: 'blue', strokeWidth: 1.5});
var pP = board.create('point', [5.5, 2], {size: 3, color: 'red', name: 'P(5.5, 2)', withLabel: true, label: {autoPosition: false, offset: [10, 10]}});
board.create('line', [[5.5, 2], [6, 3.5]], {strokeColor: 'red', strokeWidth: 1.5, strokeDasharray: '4 4'});
board.unsuspendUpdate();
